import test from 'node:test';import assert from 'node:assert/strict';import fs from 'node:fs';
let mod;try{mod=await import('../src/registered-starlight.mjs');}catch(e){if(e.code!=='ERR_MODULE_NOT_FOUND')throw e;}
const get=()=>{assert.ok(mod,'Real registered source sampler is not implemented');return mod;};
const asset=()=>JSON.parse(fs.readFileSync(new URL('../data/registered-starlight/V-nside32.json',import.meta.url)));
const observer={latDeg:28.54,lonDeg:-81.38,utcMs:Date.parse('2026-10-04T03:00:00Z'),pressureHpa:0};
test('actual asset admitted without promoting old HYG diagnostic',()=>{const m=get(),s=m.createRegisteredStarlightSampler(asset());assert.equal(s.dataAdmitted,true);assert.equal(s.band,'V');assert.ok(s.sample(120,30).value>0);assert.throws(()=>m.createRegisteredStarlightSampler({schema:'salah-real-sky/diffuse-map/1',productionAdmissible:false}));});
test('source metadata fails closed for frame, order, unit and catalogue binding',()=>{const m=get();for(const [key,value] of [['frame','ecliptic'],['sourceSha256','0'.repeat(64)],['quantity','Wm-2'],['dataAdmitted',false],['zeroPointWm2nm',1]]){const a=asset();a[key]=value;assert.throws(()=>m.createRegisteredStarlightSampler(a));}const a=asset();a.grid.order='RING';assert.throws(()=>m.createRegisteredStarlightSampler(a));assert.throws(()=>m.createRegisteredStarlightSampler(asset(),{catalogueSha256:'0'.repeat(64)}));});
test('bad data and bad estimated masks are rejected',()=>{const m=get();for(const [field,value]of [['values',NaN],['values',-1],['estimatedFraction',-1],['estimatedFraction',1.1]]){const a=asset();a[field][0]=value;assert.throws(()=>m.createRegisteredStarlightSampler(a));}const a=asset();a.values.pop();assert.throws(()=>m.createRegisteredStarlightSampler(a));});
test('RA seam and poles are continuous, not mirrored or longitude-dependent at poles',()=>{const s=get().createRegisteredStarlightSampler(asset());for(const d of [-90,-89.99,-50,0,50,89.99,90]){assert.ok(Math.abs(s.sample(0,d).value-s.sample(360,d).value)<1e-22);const a=s.sample(-1e-8,d).value,b=s.sample(1e-8,d).value;assert.ok(Math.abs(a-b)/Math.max(a,b)<1e-6);}for(const d of [-90,90])for(const r of [0,45,170,359])assert.equal(s.sample(0,d).value,s.sample(r,d).value);});
test('equal field stays constant and interpolation does not create negative light',()=>{const m=get(),a=asset();a.values.fill(2e-9);a.estimatedFraction.fill(0);a.integratedWm2nm=8e-9*Math.PI;const s=m.createRegisteredStarlightSampler(a);for(let r=0;r<360;r+=13)for(let d=-90;d<=90;d+=7){const q=s.sample(r,d);assert.ok(Math.abs(q.value/2e-9-1)<1e-14);assert.equal(q.estimatedFraction,0);}});
test('masked estimates remain visible to consumers and strict mode marks them absent',()=>{const m=get(),a=asset();a.estimatedFraction.fill(1);const s=m.createRegisteredStarlightSampler(a);assert.equal(s.sample(30,20).estimatedFraction,1);assert.equal(s.sample(30,20,{allowEstimates:false}).defined,false);assert.equal(s.sample(30,20,{allowEstimates:false}).value,null);});
test('native HEALPix centres sample exact values with nearest sampling',()=>{const m=get(),a=asset(),s=m.createRegisteredStarlightSampler(a);for(let p=0;p<a.values.length;p+=17){const q=m.healpixCentre(a.grid.nside,p);assert.equal(m.healpixIndex(a.grid.nside,q.raDeg,q.decDeg),p);assert.equal(s.sample(q.raDeg,q.decDeg,{filter:'nearest'}).value,a.values[p]);}});
test('time seeks reversible and locations affect real map',()=>{const m=get(),s=m.createRegisteredStarlightSampler(asset()),v={type:'allsky',width:40,height:40,padding:2};const a=m.renderRegisteredStarlight(s,observer,v),b=m.renderRegisteredStarlight(s,{...observer,utcMs:observer.utcMs+21600000},v),c=m.renderRegisteredStarlight(s,observer,v);assert.deepEqual(a.radiance,c.radiance);assert.notDeepEqual(a.radiance,b.radiance);assert.notDeepEqual(a.radiance,m.renderRegisteredStarlight(s,{...observer,latDeg:-33.87,lonDeg:151.21},v).radiance);assert.equal(a.physicalComposition,false);assert.equal(a.dataAdmitted,true);});
test('invalid projection and excessive raster allocations fail before rendering',()=>{const m=get(),s=m.createRegisteredStarlightSampler(asset());assert.throws(()=>m.renderRegisteredStarlight(s,observer,{type:'other',width:20,height:20}));assert.throws(()=>m.renderRegisteredStarlight(s,observer,{type:'allsky',width:2000,height:2000},{dpr:3}));assert.throws(()=>s.sample(0,91));});
test('roll, horizon, fractional DPR and footprint supersampling preserve geometry',()=>{const m=get(),s=m.createRegisteredStarlightSampler(asset()),v={type:'camera',width:33,height:53,azDeg:180,altDeg:45,fovYDeg:85,rollDeg:0};const a=m.renderRegisteredStarlight(s,observer,v,{dpr:1.37,samplesPerAxis:2});assert.equal(a.width,45);assert.equal(a.height,73);assert.ok(a.skyPixels>0);assert.notDeepEqual(a.radiance,m.renderRegisteredStarlight(s,observer,{...v,rollDeg:90},{dpr:1.37,samplesPerAxis:2}).radiance);const below=m.renderRegisteredStarlight(s,observer,{...v,altDeg:-70,fovYDeg:10});assert.equal(below.skyPixels,0);});
